// protocol.ts
type WorkerRequest =
  | { type: 'parse'; taskId: string; buffer: ArrayBuffer }
  | { type: 'cancel'; taskId: string };

type WorkerResponse =
  | { type: 'progress'; taskId: string; processed: number; total: number }
  | { type: 'success'; taskId: string; result: ParsedSummary }
  | { type: 'cancelled'; taskId: string }
  | { type: 'error'; taskId: string; message: string };

// parser-client.ts
export class ParserClient {
  private worker = this.createWorker();
  private activeTaskId?: string;

  private createWorker() {
    const worker = new Worker(new URL('./parser.worker.ts', import.meta.url), {
      type: 'module',
      name: 'file-parser',
    });
    worker.addEventListener('error', (event) => reportWorkerCrash(event.message));
    return worker;
  }

  parse(buffer: ArrayBuffer, signal: AbortSignal): Promise<ParsedSummary> {
    const taskId = crypto.randomUUID();
    this.activeTaskId = taskId;

    return new Promise((resolve, reject) => {
      const cleanup = () => {
        signal.removeEventListener('abort', abort);
        this.worker.removeEventListener('message', receive);
      };
      const abort = () => {
        this.worker.postMessage({ type: 'cancel', taskId } satisfies WorkerRequest);
        cleanup();
        reject(signal.reason ?? new DOMException('Aborted', 'AbortError'));
      };
      const receive = (event: MessageEvent<WorkerResponse>) => {
        const message = event.data;
        if (message.taskId !== taskId) return;
        if (message.type === 'progress') {
          reportProgress(message.processed / message.total);
          return;
        }
        cleanup();
        if (this.activeTaskId !== taskId) return reject(new Error('Stale task'));
        if (message.type === 'success') resolve(message.result);
        else if (message.type === 'error') reject(new Error(message.message));
        else reject(new DOMException('Cancelled', 'AbortError'));
      };

      signal.addEventListener('abort', abort, { once: true });
      this.worker.addEventListener('message', receive);
      this.worker.postMessage({ type: 'parse', taskId, buffer } satisfies WorkerRequest, [buffer]);
      // buffer đã detached tại đây; caller không được tái sử dụng.
    });
  }

  dispose() { this.worker.terminate(); }
}

// parser.worker.ts
const cancelled = new Set<string>();
self.addEventListener('message', async (event: MessageEvent<WorkerRequest>) => {
  const request = event.data;
  if (request.type === 'cancel') { cancelled.add(request.taskId); return; }

  try {
    const bytes = new Uint8Array(request.buffer);
    const result = createAccumulator();
    for (let offset = 0; offset < bytes.length; offset += 64_000) {
      if (cancelled.delete(request.taskId)) {
        postMessage({ type: 'cancelled', taskId: request.taskId } satisfies WorkerResponse);
        return;
      }
      parseChunk(bytes.subarray(offset, offset + 64_000), result);
      if (offset % 640_000 === 0) {
        postMessage({ type: 'progress', taskId: request.taskId, processed: offset, total: bytes.length } satisfies WorkerResponse);
        await new Promise((resolve) => setTimeout(resolve, 0));
      }
    }
    postMessage({ type: 'success', taskId: request.taskId, result: finish(result) } satisfies WorkerResponse);
  } catch (error) {
    postMessage({ type: 'error', taskId: request.taskId, message: error instanceof Error ? error.message : 'Unknown error' } satisfies WorkerResponse);
  } finally {
    cancelled.delete(request.taskId);
  }
});

// Layout control Int32Array:
// [0] nextTile, [1] completedTiles, [2] cancelled
const NEXT_TILE = 0;
const COMPLETED = 1;
const CANCELLED = 2;

type SharedJob = {
  control: SharedArrayBuffer;
  input: SharedArrayBuffer;   // immutable sau khi publish
  output: SharedArrayBuffer;  // mỗi tile có một writer duy nhất
  totalTiles: number;
  tileBytes: number;
};

function runWorker(job: SharedJob) {
  const control = new Int32Array(job.control);
  const input = new Uint8Array(job.input);
  const output = new Uint8Array(job.output);

  while (Atomics.load(control, CANCELLED) === 0) {
    const tile = Atomics.add(control, NEXT_TILE, 1);
    if (tile >= job.totalTiles) break;

    const start = tile * job.tileBytes;
    const end = Math.min(start + job.tileBytes, input.length);
    processTile(input.subarray(start, end), output.subarray(start, end));

    // Publish completion sau khi tile đã ghi xong.
    Atomics.add(control, COMPLETED, 1);
    Atomics.notify(control, COMPLETED, 1);
  }
}

// Coordinator chạy trong Worker, không block browser main thread.
function waitUntilComplete(controlBuffer: SharedArrayBuffer, total: number) {
  const control = new Int32Array(controlBuffer);
  while (true) {
    const observed = Atomics.load(control, COMPLETED);
    if (observed >= total || Atomics.load(control, CANCELLED) === 1) return;
    Atomics.wait(control, COMPLETED, observed, 1_000);
  }
}

if (!globalThis.crossOriginIsolated) {
  // Fallback: partition ArrayBuffer rồi transfer từng partition cho worker.
  runWithTransferableBuffers();
}

// sw.ts
const VERSION = 'v42';
const SHELL_CACHE = `shell-${VERSION}`;
const COMPATIBLE_CACHES = new Set(['shell-v41', SHELL_CACHE]);

self.addEventListener('install', (event: ExtendableEvent) => {
  event.waitUntil(
    caches.open(SHELL_CACHE).then((cache) => cache.addAll(PRECACHE_URLS))
  );
  // Không gọi skipWaiting tự động.
});

self.addEventListener('message', (event: ExtendableMessageEvent) => {
  if (event.data?.type === 'ACTIVATE_UPDATE') {
    event.waitUntil(self.skipWaiting());
  }
});

self.addEventListener('activate', (event: ExtendableEvent) => {
  event.waitUntil((async () => {
    for (const cacheName of await caches.keys()) {
      if (cacheName.startsWith('shell-') && !COMPATIBLE_CACHES.has(cacheName)) {
        await caches.delete(cacheName);
      }
    }
    // Chỉ claim nếu page/worker protocol hỗ trợ mixed-version clients.
    await self.clients.claim();
  })());
});

