let reloading = false;
navigator.serviceWorker.addEventListener('controllerchange', () => {
  if (reloading) return;
  reloading = true;
  window.location.reload();
});

export async function activateWaitingWorker(registration: ServiceWorkerRegistration) {
  await persistUnsavedDrafts();
  registration.waiting?.postMessage({ type: 'ACTIVATE_UPDATE' });
}

type OutboxCommand = {
  operationId: string;
  entityId: string;
  sequence: number;
  baseVersion: number;
  payload: UpdatePayload;
  status: 'pending' | 'sending' | 'conflicted' | 'blocked-auth';
  leaseUntil?: number;
  attempts: number;
  retryAt: number;
};

export async function editOffline(entityId: string, patch: UpdatePayload) {
  await db.transaction('rw', db.entities, db.outbox, async () => {
    const current = await db.entities.get(entityId);
    if (!current) throw new Error('Entity not available offline');

    const operationId = crypto.randomUUID();
    const sequence = current.localSequence + 1;
    await db.entities.put(applyOptimisticPatch(current, patch, sequence));
    await db.outbox.add({
      operationId, entityId, sequence, baseVersion: current.serverVersion,
      payload: patch, status: 'pending', attempts: 0, retryAt: Date.now(),
    });
  });
}

async function sendCommand(command: OutboxCommand) {
  const response = await fetch(`/api/entities/${command.entityId}`, {
    method: 'PATCH',
    credentials: 'same-origin',
    headers: {
      'content-type': 'application/json',
      'idempotency-key': command.operationId,
      'if-match': String(command.baseVersion),
    },
    body: JSON.stringify(command.payload),
  });

  if (response.status === 401) return markBlockedByAuth(command.operationId);
  if (response.status === 409 || response.status === 412) {
    return markConflict(command.operationId, await response.json());
  }
  if (!response.ok) throw new RetryableSyncError(response.status);
  await reconcileAck(command.operationId, await response.json());
}

self.addEventListener('sync', (event: SyncEvent) => {
  if (event.tag === 'drain-outbox') event.waitUntil(drainDueCommands());
});
